changeSet.sql:
CREATE TABLE fraud_check ( id UUID PRIMARY KEY, claim_id UUID NOT NULL UNIQUE, fraud_score INT NOT NULL, status VARCHAR(40) NOT NULL, checked_at TIMESTAMP NOT NULL );
CREATE TABLE fraud_signal ( id UUID PRIMARY KEY, fraud_check_id UUID NOT NULL REFERENCES fraud_check(id), signal_type VARCHAR(80) NOT NULL, severity VARCHAR(30) NOT NULL, description TEXT NOT NULL );
CREATE TABLE document_hash_index ( id UUID PRIMARY KEY, sha256_hash CHAR(64) NOT NULL, file_size_bytes BIGINT NOT NULL, mime_type VARCHAR(120) NOT NULL, invoice_number VARCHAR(120) NULL, clinic_id UUID NULL, patient_id UUID NULL, first_seen_at TIMESTAMP NOT NULL );
